\set ON_ERROR_STOP on

-- Community operator dashboard (apps/dashboard-community). Its accounts and
-- invitations live in a dedicated `dashboard` schema of the application
-- database. The Better Auth tables mirror the schema generated by
-- `@better-auth/cli generate` for better-auth 1.7 with the admin and
-- two-factor plugins, UUID ids and database-backed rate limiting. Each user
-- owns one Firecrawl team (`teamId`), which scopes keys, usage and jobs.

CREATE SCHEMA IF NOT EXISTS dashboard;

CREATE TABLE IF NOT EXISTS dashboard."user" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "email" text NOT NULL UNIQUE,
  "emailVerified" boolean NOT NULL,
  "image" text,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "role" text,
  "banned" boolean,
  "banReason" text,
  "banExpires" timestamptz,
  "twoFactorEnabled" boolean,
  "teamId" uuid REFERENCES public.teams (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS user_team_id_unique
  ON dashboard."user" ("teamId")
  WHERE "teamId" IS NOT NULL;

CREATE TABLE IF NOT EXISTS dashboard."session" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  "expiresAt" timestamptz NOT NULL,
  "token" text NOT NULL UNIQUE,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz NOT NULL,
  "ipAddress" text,
  "userAgent" text,
  "userId" uuid NOT NULL REFERENCES dashboard."user" ("id") ON DELETE CASCADE,
  "impersonatedBy" text
);

CREATE TABLE IF NOT EXISTS dashboard."account" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  "accountId" text NOT NULL,
  "providerId" text NOT NULL,
  "userId" uuid NOT NULL REFERENCES dashboard."user" ("id") ON DELETE CASCADE,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  "scope" text,
  "password" text,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS dashboard."verification" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  "identifier" text NOT NULL,
  "value" text NOT NULL,
  "expiresAt" timestamptz NOT NULL,
  "createdAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updatedAt" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS dashboard."twoFactor" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  "secret" text NOT NULL,
  "backupCodes" text NOT NULL,
  "userId" uuid NOT NULL REFERENCES dashboard."user" ("id") ON DELETE CASCADE,
  "verified" boolean,
  "failedVerificationCount" integer,
  "lockedUntil" timestamptz
);

CREATE TABLE IF NOT EXISTS dashboard."rateLimit" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  "key" text NOT NULL UNIQUE,
  "count" integer NOT NULL,
  "lastRequest" bigint NOT NULL
);

CREATE INDEX IF NOT EXISTS session_user_id_idx ON dashboard."session" ("userId");
CREATE INDEX IF NOT EXISTS account_user_id_idx ON dashboard."account" ("userId");
CREATE INDEX IF NOT EXISTS verification_identifier_idx ON dashboard."verification" ("identifier");
CREATE INDEX IF NOT EXISTS two_factor_secret_idx ON dashboard."twoFactor" ("secret");
CREATE INDEX IF NOT EXISTS two_factor_user_id_idx ON dashboard."twoFactor" ("userId");

-- Single-use, expiring invite links. Only a SHA-256 of the token is stored;
-- the link itself is shown once to the inviting admin.
CREATE TABLE IF NOT EXISTS dashboard.invitation (
  id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  token_hash text NOT NULL UNIQUE,
  email text,
  role text NOT NULL DEFAULT 'member',
  note text,
  created_by uuid REFERENCES dashboard."user" ("id") ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  used_by uuid REFERENCES dashboard."user" ("id") ON DELETE SET NULL,
  revoked_at timestamptz,
  CONSTRAINT invitation_role_valid CHECK (role IN ('admin', 'member'))
);

CREATE INDEX IF NOT EXISTS invitation_created_at_idx
  ON dashboard.invitation (created_at DESC);

-- Append-only record of administrative and security-relevant actions.
CREATE TABLE IF NOT EXISTS dashboard.audit_log (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  actor_id uuid,
  action text NOT NULL,
  target_user_id uuid,
  target_team_id uuid,
  details jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS audit_log_created_at_idx
  ON dashboard.audit_log (created_at DESC);

REVOKE ALL ON SCHEMA dashboard FROM PUBLIC;
